function validate([hours, target]) {
  if (!Array.isArray(hours) || hours.length < 1 || hours.length > 50) return 'hours needs 1 to 50 values.';
  if (hours.some(v => !Number.isInteger(v) || v < 0 || v > 100000)) return 'Each hours value is an integer from 0 to 10^5.';
  if (!Number.isInteger(target) || target < 0 || target > 100000) return 'target is an integer from 0 to 10^5.';
  return null;
}

