function generate(rand, size) {
  const n = size === 'large' ? 50 : 1 + Math.floor(rand() * 8);
  const span = size === 'large' ? 100000 : (rand() < 0.5 ? 5 : 20);
  const hours = Array.from({ length: n }, () => Math.floor(rand() * (span + 1)));
  const pick = rand();
  let target;
  if (pick < 0.4) target = hours[Math.floor(rand() * n)];
  else if (pick < 0.5) target = 0;
  else target = Math.floor(rand() * (span + 2));
  return [hours, Math.min(target, 100000)];
}
